# Script S4. Monthly nighttime water temperature summary# Thermal Behavior of Crocodile Caves in Central Belize # Authors: Wynne, J.J., Shaffer, I.N., Roberts, J.# Script Author: J. Judson Wynne# R-Studio Version: 2025.05.1+513 (2025.05.1+513)# Table 2# Outputs:# 1. Median nighttime temperature# 2. Percent nights > 24.22 C# 3. Median nightly range# Median nightly range is calculated as:# nightly maximum temperature - nightly minimum temperature# Author: Jut Wynnelibrary(readxl)library(tidyverse)library(lubridate)# Settingsxlsx_file <- "CrocCave_Data.xlsx"threshold <- 24.22winter_start <- as.POSIXct("2022-11-01 00:00:00")winter_end <- as.POSIXct("2023-02-18 23:59:59")# Import all worksheetssheets <- excel_sheets(xlsx_file); dat <- map_dfr(sheets, function(sh){ read_excel(xlsx_file, sheet = sh) %>% mutate(Sheet = sh, Logger = str_extract(sh, "L[1-5]"), Cave = ifelse(str_detect(sh, "Croc2"), "Croc 2", "KHC")) })# Create DateTimedat <- dat %>% mutate(DateTime = as.POSIXct(paste(format(Date, "%Y-%m-%d"), format(Time, "%H:%M:%S")), format = "%Y-%m-%d %H:%M:%S"), Temp = `Temperature (C)`, Hour = hour(DateTime))# Winter subsetdat_winter <- dat %>% filter(DateTime >= winter_start, DateTime <= winter_end)# Nighttime observations# Night defined as 1800Ð0500 hnight <- dat_winter %>% filter(Hour >= 19 | Hour <= 5) %>% mutate(Month = format(DateTime, "%Y-%m"), NightDate = as.Date(DateTime)); night$NightDate[night$Hour <= 5] <- night$NightDate[night$Hour <= 5] - 1# Median nighttime temperaturemedian_temp <- night %>% group_by(Cave, Month) %>% summarize(MedianTemp = median(Temp, na.rm = TRUE), .groups = "drop")# Percent nights above thermal thresholdnight_pct <- night %>%   group_by(Cave, Month, NightDate) %>%   summarize(     AboveThreshold = min(Temp, na.rm = TRUE) > threshold, .groups = "drop") %>%   group_by(Cave, Month) %>%   summarize(PercentNights = 100 * mean(AboveThreshold), .groups = "drop")# Median nightly range# Range = nightly maximum ? nightly minimumnight_range <- night %>% group_by(Cave, Month, NightDate) %>% summarize(NightlyRange = max(Temp, na.rm = TRUE) - min(Temp, na.rm = TRUE), .groups = "drop") %>% group_by(Cave, Month) %>% summarize(MedianRange = median(NightlyRange, na.rm = TRUE), .groups = "drop")# Table generation and exporttable2 <- median_temp %>% left_join(night_pct, by = c("Cave", "Month")) %>% left_join(night_range, by = c("Cave", "Month")) %>% arrange(Cave, Month) %>% mutate(MedianTemp = round(MedianTemp, 2), PercentNights = round(PercentNights, 2), MedianRange = round(MedianRange, 2))write.csv(table2, "Table2_MoNight.csv", row.names = FALSE)